{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Pentosan polysulfate, a highly sulfated carbohydrate closely related to the query, had oral bioavailability of only 0.5–1% in healthy subjects after daily oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Dextran sulfate, another sulfated polysaccharide, is reported to have poor oral bioavailability in humans, supporting very low absorption for sulfated carbohydrates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Glucoraphanin, a sulfate-containing glycoside, showed only about 5% mean oral bioavailability in a 50-participant crossover trial, with most values far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Ginsenoside Rg3, a glycosylated natural product, exhibited low oral bioavailability in humans, consistent with poor absorption of polar glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Furosemide acyl glucuronide, a glucuronic acid-containing conjugate, had an oral bioavailability of only 0.15 ± 0.04 in humans, directly relevant to the query's glucuronic acid moiety.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Tobramycin, a highly polar aminosugar antibiotic, has low and virtually negligible oral bioavailability, requiring parenteral administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Naringin, a glycoside with multiple sugar units, has human oral bioavailability of only about 5–9%, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Phlorizin, a glucoside with multiple polar hydroxyls, is limited clinically by poor oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Glycyrrhizin, which contains a glucuronic acid disaccharide, has an absolute oral bioavailability of approximately 0.25% compared with injections in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Acarbose, a carbohydrate-based drug with multiple sugar units, has negligible absolute oral bioavailability of <2% in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an extremely polar, sulfated disaccharide containing glucuronic acid and N-acetylglucosamine sulfate. Direct human oral bioavailability measurements for closely related sulfated carbohydrates and glycosides—pentosan polysulfate (0.5–1%), dextran sulfate (poor), glycyrrhizin (~0.25%), acarbose (<2%), and furosemide acyl glucuronide (0.15%)—all fall far below 20%. The physicochemical prior of negligible passive permeability is consistent with these experimental anchors. Therefore, oral bioavailability is predicted to be low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability study exists for the exact query molecule, but multiple close structural analogues with direct human measurements all support F < 20%.",
    "Potential active uptake or transporter-mediated absorption was not experimentally assessed for the query, though no evidence suggests it would overcome the severe permeability barrier."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

